-- Replaces the Help Centre answers on the LIVE store (pgAdmin: Cauvery LIVE, database railway).
-- Generated from the built-in list in frontend/src/pages/HelpCenter.jsx so both always say the same thing.
-- The old answers are switched off (active = false), not deleted, so they can be restored.
BEGIN;
UPDATE faqs SET active = false, updated_at = now() WHERE active = true;
COMMIT;
