INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'How do I place an order?', 'Browse the store, add items to your cart and go to checkout. You need to sign in to place an order.', 'orders', 1, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'Can I cancel my order?', 'Yes, free of charge, any time before the order ships. Open My Orders and choose Cancel. If you have already paid, the full amount is refunded automatically.', 'orders', 2, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'How do I track my order?', 'Open My Orders in your account to see the status of each order. Once an order ships, the courier name and tracking number are shown there.', 'orders', 3, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'What if I receive a damaged or wrong item?', 'Raise a return from My Orders within the 7-day return period and choose the matching reason, or email support@cauverystore.in with photos. Returns for damaged, defective or wrong items are free.', 'orders', 4, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'What are the shipping charges?', 'Delivery is free on orders of ₹500 or more. Orders below ₹500 have a flat ₹40 delivery charge.', 'shipping', 5, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'How long does delivery take?', 'Sellers normally dispatch within 1-2 business days. After that, delivery usually takes 2-4 business days within the seller''s own state and 4-7 business days to the rest of India. Remote areas may take longer.', 'shipping', 6, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'Do you ship internationally?', 'No. We deliver to addresses in India only.', 'shipping', 7, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'Can I change my delivery address after ordering?', 'You can update the address before the order is shipped. Once shipped, changes are not possible.', 'shipping', 8, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'What is the return policy?', 'Most items can be returned within 7 days of delivery. If a product has a different return period, it is shown on the product page.', 'returns', 9, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'How do I initiate a return?', 'Go to your Orders page, select the item, and click ''Return''. Follow the instructions to generate a return request.', 'returns', 10, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'When will I get my refund?', 'Refunds are processed within 5-7 business days after the returned item is received and verified.', 'returns', 11, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'Are there any items that cannot be returned?', 'Yes. Innerwear, swimwear, perishable goods, clearance items, customised or made-to-order items, and products marked "No Returns" cannot be returned. You can still report them if they arrive damaged, defective or wrong.', 'returns', 12, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'How do I create an account?', 'Click on ''Login'' and then ''Register''. Fill in your details to create your Cauvery Store account in seconds.', 'account', 13, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'I forgot my password. What should I do?', 'On the login page, click ''Forgot Password'' and follow the instructions to reset it via email.', 'account', 14, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'How do I update my profile?', 'Log in and visit the Profile section. You can edit your name, email, phone number, and saved addresses.', 'account', 15, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'Can I delete my account?', 'Yes, please contact our support team at support@cauverystore.in to request account deletion.', 'account', 16, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'What payment methods do you accept?', 'UPI, credit and debit cards, net banking and wallets, all through Razorpay.', 'payments', 17, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'Is my payment information secure?', 'Absolutely. All payments are processed through Razorpay with bank-grade encryption. We do not store your payment details.', 'payments', 18, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'What should I do if my payment fails?', 'First, check if the amount was deducted. If yes, it will be refunded automatically within 5-7 days. Contact support if it does not.', 'payments', 19, true);
INSERT INTO faqs (created_at, updated_at, question, answer, category, sort_order, active) VALUES (now(), now(), 'Do you offer cash on delivery?', 'Not at present. All orders are paid online through Razorpay when you place them.', 'payments', 20, true);
